content.script:

/**
 * Prints a right-aligned right-angled triangle pattern of stars with n rows.
 * @param {number} n - The number of rows in the triangle.
 * Example: For n = 5, the output will be:
     *
    **
   ***
  ****
 *****
 */
function printRightAlignedTriangle(n) {
    for (let i = 1; i <= n; i++) {
        let row = " ".repeat(n - i) + "*".repeat(i);
        console.log(row);
    }
}

printRightAlignedTriangle(5);
